head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//유가증권예탁증서 발행기관 찾기
scwin.vScrenID = "ULDINS91300.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 유가증권예탁증서 발행기관 찾기
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS91300_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listStdCdDrInfoFindInquiry";
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    var FORN_INST_CD = dts_List.getCellData(row, "CNTR_CD3") + dts_List.getCellData(row, "FORN_INST_CD");
    var FORN_INST_NM = dts_List.getCellData(row, "FORN_INST_NM");
    $c.frame.path("../").ins_popupRtn_cdnm(FORN_INST_CD, FORN_INST_NM);
    await $c.frame.CloseFrame();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    scwin.ins_search();
};
